import os, re, json, csv, io
import xml.etree.ElementTree as ET

BASE = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

records = {}
for dirpath, dirnames, filenames in sorted(os.walk(BASE)):
    for fn in sorted(filenames):
        p = os.path.join(dirpath, fn)
        ext = fn.rsplit('.',1)[-1].lower()
        rel = os.path.relpath(p, BASE)
        if ext == 'xlsx':
            continue
        raw = open(p, 'rb').read()
        txt = raw.decode('utf-8', errors='replace')

        rec = {}
        if ext in ('md','txt','eml'):
            m = re.search(r'RECORD:\s*(CB-DOC-\d+-\d+)', txt) or re.search(r'(CB-DOC-\d+-\d+)', txt)
            rec['id'] = m.group(1) if m else None
            # table-style or colon-style control fields
            for label, key in [('Portfolio key','pkey'),('PORTFOLIO KEY','pkey'),
                               ('Evidence role','role'),('EVIDENCE ROLE','role'),
                               ('Immutable entity','entity'),('ENTITY KEY','entity'),
                               ('Referenced revision','ref_rev'),('REFERENCED REVISION','ref_rev'),
                               ('Current revision','cur_rev'),('CURRENT REVISION','cur_rev')]:
                mm = re.search(r'\|\s*'+re.escape(label)+r'\s*\|\s*([^|]+?)\s*\|', txt) or \
                     re.search(r'^'+re.escape(label)+r':\s*(.+)$', txt, re.M)
                if mm and key not in rec:
                    rec[key] = mm.group(1).strip()
        elif ext == 'json':
            d = json.loads(txt)
            rec = {'id':d.get('record_id'),'pkey':d.get('portfolio_key'),'role':d.get('evidence_role'),
                   'entity':d.get('immutable_entity_key'),'ref_rev':d.get('referenced_revision'),
                   'cur_rev':d.get('current_revision'),'body':d.get('body','')}
        elif ext == 'xml':
            t = ET.fromstring(txt)
            def x(path):
                e = t.find(path); return e.text.strip() if e is not None and e.text else None
            rec = {'id':x('record-id'),'pkey':x('portfolio-key'),'role':x('evidence-role'),
                   'entity':x('immutable-entity'),'ref_rev':x('referenced-revision'),
                   'cur_rev':x('current-revision'),'body':x('native-record') or ''}
        elif ext == 'csv':
            rdr = list(csv.DictReader(io.StringIO(txt)))
            meta = {r['key']: r['value'] for r in rdr if r.get('row_type')=='metadata'}
            rec = {'id':meta.get('record_id'),'pkey':meta.get('portfolio_key'),'role':meta.get('evidence_role'),
                   'entity':meta.get('immutable_entity_key'),'ref_rev':meta.get('referenced_revision'),
                   'cur_rev':meta.get('current_revision'),'body':meta.get('body','')}
        elif ext == 'html':
            dl = dict(re.findall(r'<dt>(.*?)</dt><dd>(.*?)</dd>', txt))
            rec = {'id':dl.get('Record'),'pkey':dl.get('Portfolio key'),'role':dl.get('Evidence role'),
                   'entity':dl.get('Entity'),'ref_rev':dl.get('Revision'),
                   'body':' '.join(re.sub('<[^>]+>','',p).split()) for p in re.findall(r'<p>(.*?)</p>', txt, re.S)[:1]}
        elif ext == 'pdf':
            parts = re.findall(r'\((.*?)\) Tj', txt)
            j = ' '.join(parts)
            def f(pat):
                mm = re.search(pat, j); return mm.group(1) if mm else None
            rec = {'id':f(r'Record: (CB-DOC-\d+-\d+)'),'pkey':f(r'Portfolio key: (CBP-031-\d+)'),
                   'role':f(r'Evidence role: ([a-z_]+)'),'entity':f(r'Immutable entity: (ENT-031-\d+)'),
                   'ref_rev':f(r'Referenced revision: (REV-[\d.]+)'),'cur_rev':f(r'Current revision: (REV-[\d.]+)')}
        # native-record text for md/txt/eml/pdf
        if 'body' not in rec or not rec.get('body'):
            if ext in ('md','txt','eml'):
                secs = re.split(r'^NATIVE RECORD$', txt, flags=re.M)
                if len(secs) >= 3:
                    body = ' '.join(secs[1].split())
                    # cut at next section heading
                    body = re.split(r'RELIANCE LIMITS|SOURCE LINEAGE|BUSINESS CONTEXT|CHRONOLOGY|PROVENANCE', body)[0].strip()
                    rec['body'] = body
                else:
                    rec['body'] = None
            elif ext == 'pdf':
                idx = j.find('NATIVE RECORD')
                rec['body'] = ' '.join(j[idx+len('NATIVE RECORD'):].split())[:600] if idx>=0 else None
        records[rec.get('id') or rel] = {**rec, '_file': rel, '_ext': ext}

print(f"parsed {len(records)} records")
