import os, re
from collections import Counter, defaultdict
BASE = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"
c = Counter()
examples = {}
for dirpath, dirnames, filenames in sorted(os.walk(BASE)):
    for fn in sorted(filenames):
        if fn.endswith('.xlsx'): continue
        txt = open(os.path.join(dirpath,fn),'rb').read().decode('utf-8', errors='replace')
        for m in re.finditer(r'[Tt]his file supplies ([a-z ]+?) evidence for (CBP-031-\d+)', txt):
            c[(m.group(1).strip(), m.group(2))] += 1
            examples.setdefault(m.group(1).strip(), os.path.relpath(os.path.join(dirpath,fn), BASE))
for (role, key), n in sorted(c.items()):
